"""
Infix to Postfix expression converter using the Shunting-Yard algorithm.

Note: The function is named `flatten_nested_dict` per the user's request,
but it actually converts infix expressions to postfix notation.
"""


def flatten_nested_dict(expression: str) -> str:
    """
    Convert an infix expression to postfix (Reverse Polish) notation.

    Supports: +, -, *, /, ^, parentheses, and multi-character operands/variables.

    Args:
        expression: A string infix expression (e.g. "A+B*C", "(A+B)*(C-D)").

    Returns:
        The equivalent postfix expression as a string.

    Raises:
        ValueError: On mismatched parentheses or invalid characters.
    """
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
    right_associative = {"^"}

    output: list[str] = []
    operator_stack: list[str] = []

    tokens = _tokenize(expression)

    for token in tokens:
        if _is_operand(token):
            output.append(token)
        elif token == "(":
            operator_stack.append(token)
        elif token == ")":
            while operator_stack and operator_stack[-1] != "(":
                output.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses: extra ')'")
            operator_stack.pop()  # discard '('
        elif token in precedence:
            while (
                operator_stack
                and operator_stack[-1] != "("
                and operator_stack[-1] in precedence
                and (
                    precedence[operator_stack[-1]] > precedence[token]
                    or (
                        precedence[operator_stack[-1]] == precedence[token]
                        and token not in right_associative
                    )
                )
            ):
                output.append(operator_stack.pop())
            operator_stack.append(token)
        else:
            raise ValueError(f"Unknown token: {token}")

    while operator_stack:
        if operator_stack[-1] == "(":
            raise ValueError("Mismatched parentheses: extra '('")
        output.append(operator_stack.pop())

    return " ".join(output)


def _tokenize(expression: str) -> list[str]:
    """Split an expression string into a list of tokens."""
    tokens: list[str] = []
    i = 0
    while i < len(expression):
        ch = expression[i]
        if ch.isspace():
            i += 1
        elif ch in "+-*/^()":
            tokens.append(ch)
            i += 1
        elif ch.isalnum() or ch == "_":
            j = i
            while j < len(expression) and (expression[j].isalnum() or expression[j] == "_"):
                j += 1
            tokens.append(expression[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {ch}")
    return tokens


def _is_operand(token: str) -> bool:
    """Return True if the token is an operand (number or variable name)."""
    return token.isalnum() or token.isidentifier()


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_simple_operators():
    assert flatten_nested_dict("A+B") == "A B +"
    assert flatten_nested_dict("A-B") == "A B -"
    assert flatten_nested_dict("A*B") == "A B *"
    assert flatten_nested_dict("A/B") == "A B /"


def test_precedence():
    # * binds tighter than +
    assert flatten_nested_dict("A+B*C") == "A B C * +"
    # + does not bind tighter than *
    assert flatten_nested_dict("A*B+C") == "A B * C +"


def test_left_associativity():
    # + and - are left-associative
    assert flatten_nested_dict("A+B-C") == "A B + C -"
    assert flatten_nested_dict("A-B+C") == "A B - C +"


def test_right_associativity():
    # ^ is right-associative
    assert flatten_nested_dict("A^B^C") == "A B C ^ ^"


def test_parentheses():
    assert flatten_nested_dict("(A+B)*C") == "A B + C *"
    assert flatten_nested_dict("A*(B+C)") == "A B C + *"
    assert flatten_nested_dict("(A+B)*(C-D)") == "A B + C D - *"


def test_nested_parentheses():
    assert flatten_nested_dict("((A+B)*C)") == "A B + C *"
    assert flatten_nested_dict("(A+(B*C))") == "A B C * +"


def test_complex_expression():
    assert flatten_nested_dict("A+B*C-D/E^F") == "A B C * + D E F ^ / -"


def test_single_operand():
    assert flatten_nested_dict("X") == "X"
    assert flatten_nested_dict("42") == "42"


def test_multi_character_operands():
    assert flatten_nested_dict("alpha+beta*gamma") == "alpha beta gamma * +"


def test_numeric_expression():
    assert flatten_nested_dict("3+4*2") == "3 4 2 * +"
    assert flatten_nested_dict("(1+2)*(3+4)") == "1 2 + 3 4 + *"


def test_whitespace_handling():
    assert flatten_nested_dict("  A +  B  * C ") == "A B C * +"


def test_mismatched_parentheses():
    import pytest
    with pytest.raises(ValueError, match="Mismatched"):
        flatten_nested_dict("(A+B")
    with pytest.raises(ValueError, match="Mismatched"):
        flatten_nested_dict("A+B)")


def test_invalid_character():
    import pytest
    with pytest.raises(ValueError, match="Invalid character"):
        flatten_nested_dict("A$B")


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])
